function peakWatch(readings, k) {
  const result = [];
  for (let s = 0; s + k <= readings.length; s++) {
    let best = readings[s];
    for (let i = s + 1; i < s + k; i++) best = Math.max(best, readings[i]);
    result.push(best);
  }
  return result;
}

function peakWatch(readings, k) {
  const deque = [];
  let head = 0;
  const result = [];
  for (let i = 0; i < readings.length; i++) {
    while (deque.length > head && readings[deque[deque.length - 1]] <= readings[i]) deque.pop();
    deque.push(i);
    if (deque[head] <= i - k) head++;
    if (i >= k - 1) result.push(readings[deque[head]]);
  }
  return result;
}
